import logging

import torch
import triton
import triton.language as tl

from flag_gems.runtime import torch_device_fn

_MAX_GRID_X = 65535  # device grid-dimension limit (Ascend coreDim <= 65535)
# Gathered-axis width range handled by the in-block vectorized gather.
_ROW_GATHER_MIN = 64
_ROW_GATHER_MAX = 16384

logger = logging.getLogger(__name__)


@triton.jit
def take_along_dim_row_gather_kernel(
    inp_ptr,
    idx_ptr,
    out_ptr,
    R,
    D_in: tl.constexpr,
    D_out: tl.constexpr,
    BLOCK: tl.constexpr,
):
    """Row-wise variant for the common case where the gathered axis fits one tile.

    The whole source row is held in registers and ``tl.gather`` performs the
    permutation with the vector unit.  A flat ``tl.load(ptr + idx)`` instead
    lowers to per-element scalar loads on some backends, which is several times
    slower than the vectorized in-block gather.
    """
    pid = tl.program_id(axis=0)
    step = tl.num_programs(axis=0)
    lanes = tl.arange(0, BLOCK)
    in_mask = lanes < D_in
    out_mask = lanes < D_out
    row = pid
    while row < R:
        src = tl.load(inp_ptr + row * D_in + lanes, mask=in_mask, other=0)
        idx = tl.load(idx_ptr + row * D_out + lanes, mask=out_mask, other=0).to(
            tl.int32
        )
        # take_along_dim does not wrap negative indices, but wrapping is a no-op
        # for the valid case and keeps the address math well defined.
        idx = tl.where(idx < 0, idx + D_in, idx)
        valid = out_mask & (idx >= 0) & (idx < D_in)
        safe_idx = tl.where(valid, idx, 0)
        vals = tl.gather(src, safe_idx, 0)
        tl.store(out_ptr + row * D_out + lanes, vals, mask=valid)
        row += step


@triton.jit
def take_along_dim_kernel(
    inp_ptr,
    idx_ptr,
    out_ptr,
    R,
    D_in,
    D_out,
    N,
    LONG: tl.constexpr,
    BLOCK_SIZE: tl.constexpr,
):
    pid = tl.program_id(axis=0)
    # Grid-stride loop: the launch grid is capped (see _MAX_GRID_X),
    # so a program may have to process several blocks for large ``N``.
    step = tl.num_programs(axis=0) * BLOCK_SIZE
    block_start = pid * BLOCK_SIZE
    while block_start < N:
        offs = block_start + tl.arange(0, BLOCK_SIZE)
        if LONG:
            offs = offs.to(tl.int64)
        mask = offs < N

        # Decompose the flat output offset into (row, col) over the (R, D_out) grid.
        r = offs // D_out

        idx = tl.load(idx_ptr + offs, mask=mask, other=0)
        if LONG:
            idx = idx.to(tl.int64)
        # take_along_dim does not wrap negative indices, but wrapping here is a
        # harmless no-op for the valid (already non-negative) case and keeps the
        # kernel address math well defined.
        idx = tl.where(idx < 0, idx + D_in, idx)

        valid = (idx >= 0) & (idx < D_in)
        # Reduce the check to a scalar: a per-lane ``device_assert`` costs the
        # whole kernel ~1.6x on Ascend, while the reduction reports the same
        # error (masked-out lanes count as valid).
        tl.device_assert(
            tl.sum((valid | (~mask)).to(tl.int32)) == BLOCK_SIZE,
            "take_along_dim(): index out of range",
        )

        # Clamp the address rather than masking the load (see ``take``): the
        # non-affine load mask costs 1.6x on this backend.
        in_off = r * D_in + tl.where(valid, idx, 0)
        vals = tl.load(inp_ptr + in_off, mask=mask, other=0)
        tl.store(out_ptr + offs, vals, mask=mask)
        block_start += step


def _launch(inp2d, idx2d, out2d):
    R, D_in = inp2d.shape
    _, D_out = idx2d.shape
    N = out2d.numel()
    if N == 0:
        return
    # Rows that fit one tile use the vectorized in-block gather; wider rows
    # (rare) and dtypes `tl.gather` does not accept fall back to the flat kernel.
    gather_dtypes = (torch.float16, torch.float32, torch.bfloat16, torch.int8)
    width = max(D_in, D_out)
    # Too narrow a row means one tiny program per row, which is slower than the
    # flat kernel; too wide a row cannot be staged in one tile.
    if _ROW_GATHER_MIN <= width <= _ROW_GATHER_MAX and inp2d.dtype in gather_dtypes:
        block = max(1, triton.next_power_of_2(max(D_in, D_out)))
        grid = (min(R, _MAX_GRID_X),)
        with torch_device_fn.device(inp2d.device):
            take_along_dim_row_gather_kernel.run(
                inp2d,
                idx2d,
                out2d,
                R,
                D_in,
                D_out,
                BLOCK=block,
                grid=grid,
                warmup=False,
            )
        return
    block_size = 1024
    grid = (min(triton.cdiv(N, block_size), _MAX_GRID_X),)
    with torch_device_fn.device(inp2d.device):
        take_along_dim_kernel.run(
            inp2d,
            idx2d,
            out2d,
            R,
            D_in,
            D_out,
            N,
            LONG=N >= 2**31,
            BLOCK_SIZE=block_size,
            grid=grid,
            warmup=False,
        )


def _prepare(input, indices, dim):
    """Reduce take_along_dim to a 2D (R, D) gather.

    Returns (inp2d, idx2d, out_shape, restore) where ``restore`` maps the flat
    (R, D_out) output back to the final tensor layout.
    """
    if dim is None:
        # Flatten the input; the result has the shape of ``indices``.
        inp2d = input.reshape(1, -1).contiguous()
        idx2d = indices.reshape(1, -1).contiguous()
        # dim=None flattens both operands; the result is 1-D.
        out_shape = (indices.numel(),)

        def restore_flat(out2d):
            return out2d.reshape(out_shape)

        return inp2d, idx2d, out_shape, restore_flat

    if input.ndim != indices.ndim:
        raise RuntimeError(
            "take_along_dim: input and indices should have the same "
            f"number of dimensions, but got {input.ndim} dimensions for input, "
            f"and {indices.ndim} dimensions for indices"
        )

    dim = dim % input.ndim

    # Broadcast every non-``dim`` axis; the ``dim`` axis keeps each tensor's own
    # size (input provides the value space, indices the output extent).
    batch_shape = []
    for d in range(input.ndim):
        if d == dim:
            batch_shape.append(1)
        else:
            batch_shape.append(max(input.shape[d], indices.shape[d]))

    inp_shape = list(batch_shape)
    inp_shape[dim] = input.shape[dim]
    idx_shape = list(batch_shape)
    idx_shape[dim] = indices.shape[dim]

    inp_b = input.broadcast_to(inp_shape)
    idx_b = indices.broadcast_to(idx_shape)

    # Move ``dim`` to the last axis and collapse the batch dims into rows.
    inp_p = inp_b.movedim(dim, -1).contiguous()
    idx_p = idx_b.movedim(dim, -1).contiguous()

    D_in = input.shape[dim]
    D_out = indices.shape[dim]
    inp2d = inp_p.reshape(-1, D_in)
    idx2d = idx_p.reshape(-1, D_out)

    # Final output shape: broadcasted batch dims with the ``dim`` axis == D_out.
    out_shape = list(batch_shape)
    out_shape[dim] = D_out
    out_shape = tuple(out_shape)
    permuted_shape = tuple(idx_p.shape)

    def restore_nd(out2d):
        return out2d.reshape(permuted_shape).movedim(-1, dim).contiguous()

    return inp2d, idx2d, out_shape, restore_nd


def take_along_dim(input, indices, dim=None):
    logger.debug("GEMS TAKE_ALONG_DIM")
    if input.device != indices.device:
        raise RuntimeError("input and indices must be on the same device")
    inp2d, idx2d, out_shape, restore = _prepare(input, indices, dim)
    out2d = torch.empty(idx2d.shape, device=input.device, dtype=input.dtype)
    _launch(inp2d, idx2d, out2d)
    return restore(out2d)


def take_along_dim_out(input, indices, dim=None, *, out):
    logger.debug("GEMS TAKE_ALONG_DIM_OUT")
    if not (input.device == indices.device == out.device):
        raise RuntimeError("input, indices and out must be on the same device")
    if out.dtype != input.dtype:
        raise RuntimeError(f"out must have dtype {input.dtype}, but got {out.dtype}")
    inp2d, idx2d, out_shape, restore = _prepare(input, indices, dim)
    out2d = torch.empty(idx2d.shape, device=input.device, dtype=input.dtype)
    _launch(inp2d, idx2d, out2d)
    result = restore(out2d)
    if tuple(out.shape) != tuple(result.shape):
        out.resize_(result.shape)
    out.copy_(result)
    return out
